"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3378],{3732(e){e.exports=JSON.parse('{"title":"\uc9c0\ub09c 3\uc8fc\uc5d0 \ubabb \ub2e4\ud55c \uc774\uc57c\uae30","date":"2025-10-10","coverUrl":"/kudzu-based-bench/assets/notion/90fbc18f9874573c.png","html":"<h1 data-notion-block-id=\\"279e548d-8a8e-80b1-b84b-e04624182a88\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"286e548d-8a8e-8033-986f-d324469fcb19\\" id=\\"286e548d-8a8e-8033-986f-d324469fcb19\\"><code>node_modules</code>\ub97c \uac00\uafb8\ub294 \ubc95\uce59</h2><a href=\\"https://blog.val.town/gardening-dependencies\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.val.town/gardening-dependencies</a><p data-notion-block-id=\\"286e548d-8a8e-80a7-8e8a-c0bfee17e7bd\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub2e4\uc2dc\ud53c, \ucd5c\uadfc\uc5d0 <a href=\\"https://ones-to-watch.ethansup.net/news/post/262e548d-8a8e-80eb-9e8b-cd0868f2c950#27be548d-8a8e-8017-a474-e98c3e77a1cb\\">npm \uacf5\uae09\ub9dd \uacf5\uaca9</a>\uc774 \uc788\uc5c8\uace0, \uadf8\ub807\uae30\uc5d0 \ud574\ub2f9 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \ud574\ub2f9 \uc885\uc18d\uc131\uc774 \ud544\uc694\ud55c\uc9c0, \uc5b4\ub5bb\uac8c \ud328\ud0a4\uc9c0 \ud06c\uae30\ub97c \ubd84\uc11d\ud574\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uac04\ub2e8\ud558\uc9c0\ub9cc, \uac80\uc99d\ub41c \uc88b\uc740 \ubc29\uc2dd\uc774\ubbc0\ub85c, \uc54c\uc544\ub450\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"286e548d-8a8e-80c2-8286-e59dfd666c46\\" id=\\"286e548d-8a8e-80c2-8286-e59dfd666c46\\">\uc5e3\uc9c0 \ucf00\uc774\uc2a4\ub97c \uc704\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \ub108\ubb34 \ub9ce\ub2e4.</h2><a href=\\"https://43081j.com/2025/09/bloat-of-edge-case-libraries\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://43081j.com/2025/09/bloat-of-edge-case-libraries</a><p data-notion-block-id=\\"288e548d-8a8e-806a-8282-f955192c04d9\\">\ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc774 \uc0ac\uc6a9\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac \uc911\uc5d0\uc11c, \ud45c\uc900 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc544\ub2cc, \uc5e3\uc9c0 \ucf00\uc774\uc2a4\ub9cc\uc744 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc9c4, \ud558\uc9c0\ub9cc \uad00\ub9ac\ub418\uace0 \uc788\uc9c0 \uc54a\uac70\ub098 \ubb34\uac70\uc6b4 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \ub108\ubb34 \ub9ce\ub2e4\ub294 \uac83\uc744 \uc9c0\uc801\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub610\ud55c \uae00\uc5d0\uc11c\uc640 \uac19\uc774 <a href=\\"https://ones-to-watch.ethansup.net/news/post/43f27c92-8790-48e3-904c-82a7fab89e70#8d21a27c-c00e-4e7c-a4a9-4786e0ac9750\\">e18e</a>\uac19\uc740 \uc0dd\ud0dc\uacc4\ub97c \uc548\uc804\ud558\uace0 \ube60\ub974\uac8c \ub9cc\ub4dc\ub824\ub294 \ub2e8\uccb4\uc758 \ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\uac70\ub098, <a href=\\"https://ones-to-watch.ethansup.net/news/post/262e548d-8a8e-80eb-9e8b-cd0868f2c950#27be548d-8a8e-8017-a474-e98c3e77a1cb\\">\ud328\ud0a4\uc9c0 \uad00\ub9ac\uc790\ub97c \ud1b5\ud574 \uc545\uc131\ucf54\ub4dc\ub97c \uad00\ub9ac</a>\ud558\ub294 \uac83\uc744 \ucd94\uac00\ub85c \ucd94\ucc9c\ub4dc\ub9ac\ubbc0\ub85c, \uaf2d \ud604\uc7ac \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc801\uc6a9\ud588\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"286e548d-8a8e-80f4-9d14-d6b83dfb6b1a\\" id=\\"286e548d-8a8e-80f4-9d14-d6b83dfb6b1a\\">Next.js\uc758 \uc140\ud504 \ud638\uc2a4\ud305\uc758 \ud655\uc7a5\uc131 \uac16\ucd94\uae30</h2><a href=\\"https://dlhck.com/thoughts/the-complete-guide-to-self-hosting-nextjs-at-scale\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dlhck.com/thoughts/the-complete-guide-to-self-hosting-nextjs-at-scale</a><p data-notion-block-id=\\"286e548d-8a8e-8023-8101-ecb2079a218b\\">\uac04\ub2e8\ud55c \uc791\uc5c5\ub4e4\uc774\uc9c0\ub9cc, Next.js\uc758 \uc218\ud3c9 \ud655\uc7a5\uacfc \ub2e4\ub978 \uae30\ub2a5\uc744 \uc218\uc6d4\ud558\uac8c \uc0ac\uc6a9\ud558\uae30 \uc704\ud574\uc11c \ud574\uc57c \ud558\ub294 \ud301\uc744 \uc801\uc5b4\ub454 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/256e548d-8a8e-8099-8cda-cc9600052b7d#259e548d-8a8e-8042-bfc4-d1ef4d79191c\\">React \ucee4\ubba4\ub2c8\ud2f0\ub294 \uc5b4\ub514\ub85c \uac00\ub294\uac00</a>\uc5d0\uc11c\ub3c4 \ub098\uc624\ub4ef\uc774, \ucd5c\uadfc\uc5d0\ub294 Next.js \uc140\ud504\ud638\uc2a4\ud305\uc774\ub098, adapter(16\ubc84\uc804\uc5d0 \ub098\uc62c \uc608\uc815)\uc5d0\ub3c4 \uc9d1\uc911\ud558\uace0 \uc788\uc73c\ubbc0\ub85c, vercel\uc5d0 \ubc30\ud3ec\ud558\uc9c0 \uc54a\ub294 \ud658\uacbd\uc744 \uad6c\ucd95\ud560 \uc608\uc815\uc774\ub77c\uba74 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"286e548d-8a8e-800c-917d-cf2b1954d37f\\" id=\\"286e548d-8a8e-800c-917d-cf2b1954d37f\\">2025\ub144, \uc0c1\ud0dc \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 \uc548\ub155\ud558\uc2e0\uac00\uc694.</h2><a href=\\"https://stefvanwijchen.com/react-and-redux-in-2025/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://stefvanwijchen.com/react-and-redux-in-2025/</a><p data-notion-block-id=\\"288e548d-8a8e-8071-8977-d41355d2a7b1\\">Redux\uc640 \ub2e4\ub978 \uc0c1\ud0dc \ub77c\uc774\ube0c\ub7ec\ub9ac\ubcf4\ub2e4 \uc88b\uc740 \uc810\uc744 \ud45c\uc2dc\ud558\uba70 \ub54c\uc5d0 \ub530\ub77c Redux\uac00 \uc88b\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/15ee548d-8a8e-80b5-9d6e-cfa07648afc4#162e548d-8a8e-801a-b46c-cfbfc545e5d0\\">\uc804\uc5ed \uc0c1\ud0dc \uad00\ub9ac\uc640 \uc2dc\uc0ac\ud558\ub294 \ubc14</a>\uc5d0\uc11c\ub3c4 \ub098\uc624\ub4ef\uc774, \uc218\ub9ce\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc788\uace0, \uc0c1\ud0dc \uad00\ub9ac \ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 \uae30\ubcf8 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \ub2e4\ub978 \uba74\uc744 \ubcf4\uace0 \uc120\ud0dd\ud574\uc57c \ud560 \uc218\ub3c4 \uc788\uace0, \ud639\uc740 \uc774 \uae00\uc5d0\uc11c \ub9d0\ud55c\ub300\ub85c Redux\uc758 \uc7a5\uc810\uc744 \ubcf4\uace0 \uc120\ud0dd\ud574\uc57c \ud560 \uacbd\uc6b0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc XState\ubcf4\ub2e4\ub294 \ub35c\ud55c \uac15\uc81c\uc131\uacfc \uc88b\uc740 \uc608\uce21 \uac00\ub2a5\uc131\uacfc \uc774\ub97c \ub3c4\uc640\uc8fc\ub294 \uc0dd\ud0dc\uacc4\ub294 \uc88b\uc544\ubcf4\uc785\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"279e548d-8a8e-801a-afde-d970ae4384b8\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"286e548d-8a8e-80d6-99a3-ebc6765db09a\\" id=\\"286e548d-8a8e-80d6-99a3-ebc6765db09a\\">react-fast-refresh\uac00 \ud558\ub294 \uc77c</h2><a href=\\"https://leapcell.io/blog/react-fast-refresh\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://leapcell.io/blog/react-fast-refresh</a><p data-notion-block-id=\\"286e548d-8a8e-8019-9275-f0ef24c8f26b\\">Hot reload\uc640 Live reload(\ub2e4\ub974\uac8c \ud45c\ud604\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub3c4 \uc788\uc9c0\ub9cc \uc774\ub807\uac8c \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4)\uc758 \ucc28\uc774, \uadf8\ub9ac\uace0 react-fast-refresh\uac00 \uc5b4\ub5a4 \uc804\ub7b5\uc744 \ucde8\ud558\uace0 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c React \uc218\uc900\uc758 Hot reload\ub97c \uad6c\ud604\ud588\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"286e548d-8a8e-80da-b878-d6868d449d8f\\" id=\\"286e548d-8a8e-80da-b878-d6868d449d8f\\"><code>setTimeout(callback, 0)</code>\uc740 \uc65c \ubc14\ub85c \uc2e4\ud589\ub418\uc9c0 \uc54a\uc744\uae4c</h2><a href=\\"https://nolanlawson.com/2025/08/31/why-do-browsers-throttle-javascript-timers/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nolanlawson.com/2025/08/31/why-do-browsers-throttle-javascript-timers/</a><p data-notion-block-id=\\"288e548d-8a8e-806d-b666-d47889a91a93\\">setTimeout\uc774 \uc2a4\ub85c\ud2c0\ub9c1\uc774 \uc874\uc7ac\ud558\uace0, \ub610\ud55c \uc65c setTimeout\uc5d0 \uc2a4\ub85c\ud2c0\ub9c1\uc774 \uc874\uc7ac\ud558\uac8c \ub418\uc5c8\ub294\uc9c0, \uc5b4\ub5a4 \ub300\uccb4\uc81c\uac00 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"288e548d-8a8e-80e9-ab37-eb78ff724d76\\" id=\\"288e548d-8a8e-80e9-ab37-eb78ff724d76\\">\uc11c\ubc84 \uc0c1\ud0dc\uc5d0\uc11c \ud30c\uc0dd\ub41c \uac12 \uad00\ub9ac\ud558\uae30</h2><a href=\\"https://tkdodo.eu/blog/deriving-client-state-from-server-state\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/deriving-client-state-from-server-state</a><p data-notion-block-id=\\"288e548d-8a8e-80cc-a1fd-f1c0607d6e7d\\">\uc11c\ubc84 \uc0c1\ud0dc\uc5d0\uc11c \ud30c\uc0dd\ub41c \ud074\ub77c\uc774\uc5b8\ud2b8 \uc0c1\ud0dc\ub97c \uc5b4\ub5bb\uac8c \ud558\uba74 \uc798 \uad00\ub9ac\ud560 \uc218 \uc788\uc744\uc9c0 \uace0\ubbfc\ud558\uace0, \uace0\ubbfc \uacb0\uacfc\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"288e548d-8a8e-8024-8a1b-d3abf3059530\\" id=\\"288e548d-8a8e-8024-8a1b-d3abf3059530\\">\uc811\uadfc\uc131\uc740, \ud56d\uc0c1 \ub4b7\uc804\uc774 \ub41c\ub2e4.</h2><a href=\\"https://alice.boxhall.au/articles/a-threat-model-for-accessibility-on-the-web/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://alice.boxhall.au/articles/a-threat-model-for-accessibility-on-the-web/</a><p data-notion-block-id=\\"288e548d-8a8e-80b7-941f-c2b9e9afbaaa\\">\uc811\uadfc\uc131\uc774 \uc6f9 \uac1c\ubc1c\uc790 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uc6f9 \ud45c\uc900\uc744 \ub9cc\ub4dc\ub294\ub370\uc5d0 \uc788\uc5b4\uc11c\ub3c4 \ubc29\uce58\ub418\uace0 \uc788\uc74c\uc744 \uc54c\ub824\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0, \uc6f9 \ud45c\uc900\uc758 \uadfc\ubcf8\uc801\uc778 \ubb38\uc81c\uc640 <a href=\\"https://open-ui.org/\\">open ui</a>\uac19\uc740 \ud45c\uc900\uc744 \uc27d\uac8c \ubcf4\uc5ec\uc8fc\ub294 \uc0ac\ub840 \ub610\ud55c \uc18c\uac1c\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"27ee548d-8a8e-8041-b84a-ce939312e763\\" id=\\"27ee548d-8a8e-8041-b84a-ce939312e763\\">New Archtecture, \ud6c4\uae30</h2><a href=\\"https://shopify.engineering/react-native-new-architecture\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shopify.engineering/react-native-new-architecture</a><p data-notion-block-id=\\"27ee548d-8a8e-80db-b481-f37d50089f7c\\">Shopify\uc5d0\uc11c, React Native \uc571\uc744 New Architecture\ub85c \uc5c5\uadf8\ub808\uc774\ub4dc \ud558\uae30 \uc704\ud574\uc11c \uc5b4\ub5a4 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc804\ub7b5\uc744 \uc138\uc6e0\uace0, \uc5b4\ub5a4 \uacfc\uc815\uacfc \uc5b4\ub5a4 \ubb38\uc81c\uc810\uc774 \uc788\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"27ee548d-8a8e-801b-90b5-f78b87ce3ae8\\" id=\\"27ee548d-8a8e-801b-90b5-f78b87ce3ae8\\">Vite\uc5d0\uc11c \ucee4\uc2a4\ud140 SSR \uad6c\ucd95\ud558\uae30</h2><a href=\\"https://www.patron.com/blog/post/vite-ssr-getstaticprops-replacement/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.patron.com/blog/post/vite-ssr-getstaticprops-replacement/</a><h2 data-notion-block-id=\\"279e548d-8a8e-8005-be80-fc4eb1eae698\\" id=\\"279e548d-8a8e-8005-be80-fc4eb1eae698\\">Color Animation \ud301</h2><a href=\\"https://www.joshwcomeau.com/animation/color-shifting/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/animation/color-shifting/</a><h2 data-notion-block-id=\\"288e548d-8a8e-8045-8e22-e5f25494fd04\\" id=\\"288e548d-8a8e-8045-8e22-e5f25494fd04\\">Rolldown \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud6c4\uae30</h2><a href=\\"https://tech.plaid.co.jp/perf-server-build\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tech.plaid.co.jp/perf-server-build</a><h2 data-notion-block-id=\\"288e548d-8a8e-80dd-94e2-e6d79c9a914c\\" id=\\"288e548d-8a8e-80dd-94e2-e6d79c9a914c\\">Tanstack DB\uac00 \ud544\uc694\ud560 \ub54c</h2><a href=\\"https://frontendatscale.com/blog/tanstack-db/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendatscale.com/blog/tanstack-db/</a><p data-notion-block-id=\\"288e548d-8a8e-8023-aabb-d6dcf9187e67\\"></p><p data-notion-block-id=\\"27ee548d-8a8e-809c-9688-e4cb8d794163\\"></p>"}')}}]);